package com.sentinel.aml.service;
import com.sentinel.aml.model.*; import com.sentinel.aml.repository.*; import org.junit.jupiter.api.*; import org.mockito.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
class DetectionServiceTest {
 @Test void highRiskJurisdictionCreatesAlert(){ TransactionRepository txRepo=mock(TransactionRepository.class);AlertRepository alertRepo=mock(AlertRepository.class);RuleSettings settings=mock(RuleSettings.class);when(settings.enabled(anyString())).thenReturn(false);when(settings.enabled("HIGH_RISK_JURISDICTION")).thenReturn(true);when(settings.value("HIGH_RISK_JURISDICTIONS","IR,KP,SY")).thenReturn("IR,KP");when(settings.weight("HIGH_RISK_JURISDICTION",90)).thenReturn(90);when(alertRepo.findFirstByAccountIdAndRuleNameAndStatusInOrderByCreatedAtDesc(any(),anyString(),any())).thenReturn(Optional.empty());DetectionService service=new DetectionService(txRepo,alertRepo,settings); Customer c=new Customer();c.setFullName("Demo");c.setCustomerReference("C1");Account a=new Account();a.setCustomer(c); AmlTransaction tx=new AmlTransaction();tx.setAccount(a);tx.setJurisdiction("IR");tx.setAmountInInr(new BigDecimal("100"));tx.setTransactionTime(LocalDateTime.now());service.evaluate(tx);verify(alertRepo).save(argThat(alert -> alert.getRuleName().equals("HIGH_RISK_JURISDICTION") && alert.getRiskScore()==90)); }
}
